mod solution;

fn valid(_input: &str, actual: &str, expected: &str) -> bool { actual == expected }

fn main() {
    let cases = [
        ("insert5 insert2 insert8 insert1 delete2 inorder","1,5,8"),
        ("insert4 insert2 delete4 inorder","2"),
        ("insert2 insert2 insert1 inorder","1,2"),
        ("insert3 insert1 insert5 delete3 inorder","1,5"),
        ("insert9 delete9 insert4 inorder","4"),
        ("  \ninsert5 insert2 insert8 insert1 delete2 inorder\n  ","1,5,8"),
        ("\ninsert9 delete9 insert4 inorder\n","4")
    ];
    for (i,(input,expected)) in cases.iter().enumerate() {
        let actual = solution::solve(input);
        if !valid(input,&actual,expected) { eprintln!("PRIVATE CASE {} FAILED",i+1); std::process::exit(1); }
    }
    println!("PASS treap");
}
